        // We need to count: da + db + dc <= l AND (x + da) + (y + db) <= (z + dc)
        // i.e., x + y + da + db <= z + dc
        // i.e., da + db - dc <= z - x - y

        long diff = z - x - y;

        // If diff < 0, then x + y > z initially, so even with no increments, the triangle is valid.
        // But we still need to count cases where after increments, x + y <= z.
        // Actually, if diff < 0, it's possible that after adding to z and not to x,y, the condition fails.

        // Let's count the number of (da, db, dc) with da+db+dc <= l and da+db-dc <= diff
        // Let s = da + db, then s - dc <= diff, and s + dc <= l
        // So dc >= s - diff and dc <= l - s
        // Also dc >= 0, so dc >= max(0, s - diff)
        // And s >= 0

        // For a given s, the number of (da, db) with da+db=s is s+1
        // For a given s, the number of valid dc is:
        //   if s - diff <= 0: dc can be from 0 to l-s, so (l-s+1) values
        //   else: dc can be from s-diff to l-s, so (l-s - (s-diff) + 1) = (l - 2s + diff + 1) values
        //   but only if s-diff <= l-s, i.e., 2s >= diff + ... wait
        //   Actually we need s-diff <= l-s, i.e., 2s >= diff... no, s-diff <= l-s means 2s >= diff? No:
        //   s - diff <= l - s  =>  2s <= l + diff
        //   And we need s - diff <= l - s, and also s - diff >= 0 for the lower bound to matter.

        // Let me re-derive:
        // For fixed s = da + db (s >= 0), number of (da,db) pairs = s + 1
        // dc must satisfy: max(0, s - diff) <= dc <= l - s
        // This is valid only if max(0, s - diff) <= l - s
        // Case 1: s - diff <= 0, i.e., s <= diff
        //   Then lower bound is 0, upper bound is l - s
        //   Valid if 0 <= l - s, i.e., s <= l
        //   Number of dc values = l - s + 1
        // Case 2: s - diff > 0, i.e., s > diff
        //   Then lower bound is s - diff, upper bound is l - s
        //   Valid if s - diff <= l - s, i.e., 2s <= l + diff
        //   Number of dc values = (l - s) - (s - diff) + 1 = l - 2s + diff + 1

        long invalidWays = 0;

        // s ranges from 0 to l
        // For s from 0 to min(diff, l): case 1
        // For s from max(diff+1, 0) to l: case 2, but only if 2s <= l + diff

        long maxS1 = Math.min(diff, l);
        for (long s = 0; s <= maxS1; s++) {
            // Case 1: s <= diff
            // Number of dc = l - s + 1
            invalidWays += (s + 1) * (l - s + 1);
        }

        long minS2 = Math.max(diff + 1, 0);
        long maxS2 = Math.min(l, (l + diff) / 2);
        for (long s = minS2; s <= maxS2; s++) {
            // Case 2: s > diff and 2s <= l + diff
            long numDc = l - 2 * s + diff + 1;
            if (numDc > 0) {
                invalidWays += (s + 1) * numDc;
            }
