        // i.e., x + y - z > c - a - b
        // Let d = c - a - b. We need x + y - z > d.
        // Note: if d < 0, then even without any additions, the triangle is non-degenerate.

        long d = c - a - b;

        // Total number of non-negative integer solutions to x + y + z <= l is C(l+3, 3).
        // We need to count the number of solutions where x + y - z <= d (the bad cases).
        // Then answer = total - bad.

        // Total ways: sum_{s=0}^{l} C(s+2, 2) = C(l+3, 3)
        long total = (l + 1) * (l + 2) * (l + 3) / 6;

