            // = Sum (s+1)(l+1-s)
            // Let n = s1_end
            // Sum_{s=0}^{n} (s+1)(l+1-s)
            // = (l+1) Sum(s+1) - Sum(s(s+1))
            // = (l+1) * (n+1)(n+2)/2 - Sum(s^2 + s)
            // = (l+1)(n+1)(n+2)/2 - [n(n+1)(2n+1)/6 + n(n+1)/2]
            // = (l+1)(n+1)(n+2)/2 - n(n+1)(2n+1)/6 - n(n+1)/2
            // = (n+1)[(l+1)(n+2)/2 - n(2n+1)/6 - n/2]
            // = (n+1)[(l+1)(n+2)/2 - n(2n+1+3)/6]
            // = (n+1)[(l+1)(n+2)/2 - n(2n+4)/6]
            // = (n+1)[(l+1)(n+2)/2 - n(n+2)/3]
            // = (n+1)(n+2)[(l+1)/2 - n/3]
            // = (n+1)(n+2)(3(l+1) - 2n)/6

            long n = s1_end;
            // To avoid floating point, compute carefully
            // (n+1)(n+2)(3(l+1) - 2n) / 6
            long term1 = (n + 1) * (n + 2);
            long term2 = 3 * (l + 1) - 2 * n;
            // We need to divide by 6. At least one of term1 or term2 is even, and one is divisible by 3.
            // Let's just do the division carefully.
            long numerator = term1 * term2;
            result += numerator / 6;
        }

        // Case 2: s from max(t+1, 0) to min(l, (l+t+1)/2)
        long s2_start = Math.max(t + 1, 0);
        long s2_end = Math.min(l, (l + t + 1) / 2);
        if (s2_end >= s2_start) {
            // Sum_{s=s2_start}^{s2_end} (s+1)(l - 2s + t + 1)
            // Let m = l + t + 1
            // Sum (s+1)(m - 2s)
            // = Sum (s+1)m - 2(s+1)s
            // = m * Sum(s+1) - 2 * Sum(s^2 + s)

            long n1 = s2_start;
            long n2 = s2_end;
            long m = l + t + 1;

            // Sum_{s=n1}^{n2} (s+1) = Sum_{s=n1}^{n2} s + (n2-n1+1)
            // = (n1+n2)(n2-n1+1)/2 + (n2-n1+1)
            // = (n2-n1+1)(n1+n2+2)/2

            // Sum_{s=n1}^{n2} (s^2 + s) = Sum s^2 + Sum s
            // Sum s^2 from n1 to n2 = sumSquares(n2) - sumSquares(n1-1)
            // Sum s from n1 to n2 = sumLinear(n2) - sumLinear(n1-1)

            long count = n2 - n1 + 1;
            long sumS = (n1 + n2) * count / 2;
            long sumS2 = sumSquares(n2) - sumSquares(n1 - 1);

            long sumTerm1 = m * ((n2 - n1 + 1) * (n1 + n2 + 2) / 2);
            long sumTerm2 = 2 * (sumS2 + sumS);

            result += sumTerm1 - sumTerm2;
        }

        return result;
    }

    static long sumSquares(long n) {
        if (n <= 0) return 0;
        return n * (n + 1) * (2 * n + 1) / 6;
    }
}
