        // Let d = c - a - b

        // Case 1: d < 0
        // If d < 0, then x + y - z <= d. Since x,y,z >= 0, x+y-z >= -z >= -l (since z <= l).
        // Actually, x+y-z can be negative. The minimum value of x+y-z is when x=0,y=0,z=l, giving -l.
        // So if d < -l, then there are no invalid cases.
        // If -l <= d < 0, we need to count x+y-z <= d with x+y+z <= l.

        // Let's use a different approach. Let's iterate over z (the increase of the largest stick).
        // For a fixed z, we need x + y <= l - z and x + y <= c - a - b + z - 1 (for the strict inequality a+x+b+y > c+z)
        // Wait, the condition for valid is a+x + b+y > c+z, so invalid is a+x + b+y <= c+z.
        // So for fixed z, invalid requires x + y <= c - a - b + z AND x + y <= l - z.
        // So x + y <= min(c - a - b + z, l - z)
        // And x + y >= 0.
        // The number of non-negative solutions to x + y <= S is (S+1)(S+2)/2 if S >= 0, else 0.

        // So total invalid = sum over z from 0 to l of:
        //   Let S = min(c - a - b + z, l - z)
        //   If S >= 0, add (S+1)(S+2)/2, else add 0.

        // But we also need to make sure that x + y + z <= l, which is already captured by x+y <= l-z.

        // Let's compute this sum.
        long d = c - a - b;
        long invalid = 0;

        for (long z = 0; z <= l; z++) {
            long maxSum = Math.min(d + z, l - z);
            if (maxSum >= 0) {
                // Number of non-negative (x,y) with x+y <= maxSum is (maxSum+1)(maxSum+2)/2
                invalid += (maxSum + 1) * (maxSum + 2) / 2;
            }
        }

        // Total number of ways to distribute at most l among 3 sticks:
        // This is the number of non-negative integer solutions to x+y+z <= l
        // = C(l+3, 3) = (l+1)(l+2)(l+3)/6
        long total = (l + 1) * (l + 2) * (l + 3) / 6;

        long result = total - invalid;

        System.out.println(result);
    }
}
