```java
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();
        long c = sc.nextLong();
        long l = sc.nextLong();

        // Sort the sticks
        long[] sticks = {a, b, c};
        Arrays.sort(sticks);
        long x = sticks[0];
        long y = sticks[1];
        long z = sticks[2];

        // Total number of ways to distribute at most l increments among 3 sticks
        // Number of non-negative integer solutions to da + db + dc <= l
        // This is C(l+3, 3)
        long total = combination(l + 3, 3);

        // Count the number of ways where the triangle inequality is violated
        // Triangle inequality: x + y > z (since x <= y <= z, we only need to check this one)
        // Violation: x + y <= z
        // After increments: (x + da) + (y + db) > (z + dc)
        // Violation: (x + da) + (y + db) <= (z + dc)
        // Let da, db, dc >= 0, da + db + dc <= l
        // We need to count: da + db - dc <= z - x - y
        // Let k = z - x - y
        // If k < 0, then x + y > z already, so no violation possible? No wait.
        // Actually if x + y > z initially, then even with increments, we might still violate if we increase z a lot and don't increase x,y.
        // Let's think differently.

        // We want to count the number of (da, db, dc) with da, db, dc >= 0, da+db+dc <= l
        // such that (x+da) + (y+db) <= (z+dc)
        // i.e., da + db - dc <= z - x - y
        // Let s = da + db + dc <= l
        // Let t = da + db - dc
        // Note that da + db = s - dc
        // So t = s - dc - dc = s - 2*dc
        // We need s - 2*dc <= z - x - y
        // i.e., 2*dc >= s - (z - x - y)
        // i.e., dc >= (s - (z - x - y)) / 2

        // Alternatively, let's use a different approach.
        // Count the number of triples (da, db, dc) with da+db+dc <= l and da+db <= z - x - y + dc
        // Let's iterate over possible values of dc? That could be up to 3*10^5 which is acceptable.
        // But l can be up to 3*10^5, so iterating over dc from 0 to l is O(l) which is fine.

        // For a fixed dc, we need da + db <= l - dc and da + db <= z - x - y + dc
        // Let limit1 = l - dc
        // Let limit2 = z - x - y + dc
        // We need da + db <= min(limit1, limit2)
        // And da, db >= 0
        // Number of non-negative solutions to da + db <= M is (M+1)(M+2)/2 if M >= 0, else 0.

        long bad = 0;
        long k = z - x - y; // We need da + db <= k + dc

        for (long dc = 0; dc <= l; dc++) {
            long remaining = l - dc;
            if (remaining < 0) break;
            long limit = k + dc;
            if (limit < 0) {
                // No solutions for da+db <= limit since da+db >= 0
                continue;
            }
            long M = Math.min(remaining, limit);
            if (M >= 0) {
                // Number of non-negative integer pairs (da, db) with da + db <= M
                // is (M+1)(M+2)/2
                bad += (M + 1) * (M + 2) / 2;
            }
        }

        long answer = total - bad;
        System.out.println(answer);
    }

    static long combination(long n, long r) {
        if (r > n) return 0;
        if (r == 0 || r == n) return 1;
        // C(n, 3) = n*(n-1)*(n-2)/6
        if (r == 3) {
            return n * (n - 1) * (n - 2) / 6;
        }
        // General case, but here r is always 3
        return 0;
    }
}
